st=getSampleStyleSheet(); st.add(ParagraphStyle(name='CoverTitle',parent=st['Title'],fontName='Helvetica-Bold',fontSize=25,leading=30,textColor=HexColor('#193d58'),alignment=TA_CENTER,spaceAfter=10)); st.add(ParagraphStyle(name='Sub',parent=st['Normal'],fontSize=12,leading=18,alignment=TA_CENTER,textColor=HexColor('#667684'))); st.add(ParagraphStyle(name='H',parent=st['Heading2'],textColor=HexColor('#193d58'),spaceBefore=10,spaceAfter=6)); st.add(ParagraphStyle(name='Small',parent=st['BodyText'],fontSize=8.5,leading=12)); st.add(ParagraphStyle(name='CodeSmall',parent=st['Code'],fontSize=7.5,leading=10))
story=[]
story += [Spacer(1,35*mm),Paragraph('CSE4203 — Principles of Software Architecture',st['Sub']),Spacer(1,15*mm),Paragraph('SOLOQ',st['CoverTitle']),Paragraph('University Appointment &amp; Student Services System (UASSS)',st['Sub']),Spacer(1,15*mm),Paragraph('Milestone 3 — Architectural Prototype',st['Heading1']),Spacer(1,12*mm)]
cover=[['Instructor','Dr. Nada Mahmoud Hassan'],['TA','Eng. Mohamed Fareh'],['Student','Ahmed Adel — 221004576'],['Team','SoloQ (individual submission approved by instructor)'],['Date','19 November 2026']]
t=Table(cover,colWidths=[42*mm,105*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(0,-1),HexColor('#eef3f7')),('GRID',(0,0),(-1,-1),.4,HexColor('#d7e0e7')),('FONTNAME',(0,0),(0,-1),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),9),('PADDING',(0,0),(-1,-1),8)]));story += [t,Spacer(1,15*mm),Paragraph('Individual contribution',st['H']),Paragraph('Ahmed Adel (221004576): requirements review, backend and frontend prototype implementation, database schema and integrity constraints, architecture mapping, tests, quality-attribute experiment scripts, documentation and packaging — 100%.',st['BodyText']),PageBreak()]
story += [Paragraph('1. Prototype scope and architecture',st['H']),Paragraph('SoloQ is a web-based appointment system with three roles: student, department staff and administrator. The prototype carries forward the M2 layered client–server architecture: React in a separately built web container served by Nginx, a Node.js/Express REST API, PostgreSQL persistence and an isolated notification adapter for SMTP. The high-level architecture and selected technology stack are unchanged from M2.',st['BodyText'])]
rows=[['M1 requirement','Prototype implementation'],['FR1 — sign in','Student registration and JWT login; seeded staff and administrator accounts'],['FR2 — browse departments and slots','Department catalogue and open future-slot endpoints'],['FR3 — book a slot','Authenticated booking endpoint with transaction'],['FR4 — cancel own appointment','Cancellation endpoint constrained by student ownership'],['FR5 — email confirmation','SMTP adapter; console fallback when SMTP is not configured'],['FR6 — staff appointment view','Staff-scoped department appointment endpoint'],['FR7 — manage availability','Staff create and update endpoints for availability slots'],['FR8 — prevent double booking','PostgreSQL partial unique index and HTTP 409 conflict response']]
t=Table(rows,colWidths=[48*mm,115*mm],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#193d58')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,HexColor('#d7e0e7')),('VALIGN',(0,0),(-1,-1),'TOP'),('FONTSIZE',(0,0),(-1,-1),8),('PADDING',(0,0),(-1,-1),6)]));story += [t,Paragraph('2. Architectural tactics',st['H']),Paragraph('Security tactic: JWT authentication plus server-side role checks and ownership checks on protected routes. Consistency tactic: booking runs in a database transaction and PostgreSQL enforces one active appointment per slot through a partial unique index. Performance tactic: bounded availability query, department/time index and result limit. Modifiability tactic: SMTP-specific delivery is isolated behind the notification service module.',st['BodyText']),Paragraph('3. Architecture-to-code mapping',st['H'])]
rows=[['Architecture element','Implementation location'],['Web UI','web/src/'],['Static hosting / reverse proxy','web/nginx.conf, web/Dockerfile'],['API routes and startup','api/src/app.js, api/src/server.js'],['Authentication / authorization','api/src/modules/auth/, api/src/middleware/'],['Slot and appointment modules','api/src/modules/slots/, api/src/modules/appointments/'],['Notification adapter','api/src/modules/notifications/'],['Persistent data model','db/init.sql']]
t=Table(rows,colWidths=[58*mm,105*mm],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#193d58')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,HexColor('#d7e0e7')),('FONTSIZE',(0,0),(-1,-1),8),('PADDING',(0,0),(-1,-1),6)]));story += [t,Paragraph('Architecture erosion is limited by feature route modules, shared authentication middleware, a separate notification adapter, a versioned SQL schema, and tests around booking integrity. Feature modules should not import each other’s route handlers; shared behavior belongs in middleware or configuration modules.',st['BodyText']),Paragraph('4. Testing',st['H']),Paragraph('Two unit tests for booking-conflict error mapping were executed in the available environment and passed. JavaScript syntax checks also completed for the API source and test files. A PostgreSQL integration test is included and checks that the database rejects a second active appointment for the same slot; it requires a running test database. The browser/API end-to-end flow and Compose deployment still require execution on a machine with Docker and installed dependencies.',st['BodyText']),Paragraph('5. Quality attribute evidence',st['H']),Paragraph('The M1 response measures remain acceptance targets. Scripts are included for QA-1 performance (200 virtual users for 60 seconds; p95 threshold 500 ms) and QA-4 booking consistency (100 attempts against one slot; expected one HTTP 201 and the remainder HTTP 409). These experiments have not yet been run against the Docker stack, so no measured values or pass claims are reported. A QA-2 authorization checklist is also included in evidence/qa-results.md.',st['BodyText']),Paragraph('6. Design changes since M2',st['H']),Paragraph('The high-level architecture is unchanged. The prototype clarifies notification ordering: the appointment transaction commits before the SMTP attempt. If SMTP is unavailable, the booking remains committed and the failure is logged. This is recorded as ADR-007. A console notification fallback supports local demonstration without external SMTP credentials.',st['BodyText']),Paragraph('7. Run instructions',st['H']),Preformatted('cp .env.example .env\ndocker compose up --build\n# UI: http://localhost:8080\n# API health: http://localhost:4000/health\ndocker compose exec api node src/seed-demo.js',st['CodeSmall']),Paragraph('Docker Desktop / Docker Engine with Compose is required. Detailed setup, demo credentials, API endpoints, test commands and k6 instructions are provided in README.md.',st['BodyText']),Paragraph('8. Current verification status and limitations',st['H']),Paragraph('Verified here: API source syntax checks; two booking-rule unit tests pass. Not verified here: Docker Compose startup, database-backed integration test, real SMTP delivery, browser workflow, k6 performance target, 100-request race experiment and authorization checks against a live database. The current execution environment did not have Docker, and dependency installation timed out. These items are explicitly left as run-and-record tasks in evidence/qa-results.md; they must not be presented as completed measurements.',st['BodyText']),Paragraph('9. Contribution',st['H']),Paragraph('Ahmed Adel (221004576) — 100%: prototype design and implementation, architecture mapping, database schema, automated test scripts, evidence plan and documentation.',st['BodyText']),Paragraph('References',st['H']),Paragraph('[1] Dr. N. M. Hassan, “CSE4203: Principles of Software Architecture — Project Deliverables (Milestone 2, 3 &amp; 4),” course handout, 2026. [2] Dr. N. M. Hassan, “CSE4203: Principles of Software Architecture — Project Deliverables (Milestone 1),” course handout, 2026. [3] PostgreSQL Global Development Group, “PostgreSQL Documentation.” [4] Express.js, “Express Documentation.” [5] Docker, “Docker Compose Documentation.”',st['Small'])]
